#!/usr/bin/env -S deno run -A

/**
 * CI workflow generator for dprint-plugin-svgo.
 *
 * Generates `.github/workflows/ci.yml` from a programmatic TypeScript
 * definition, ensuring the workflow stays consistent and maintainable.
 *
 * @module
 */

import { stringify } from "yaml";
import $ from "dax";

// --- Configuration ---
const REPO_OWNER = "kjanat";
const REPO_NAME = "dprint-plugin-svgo";
const BRANCHES = ["master"];
const IGNORED_PATHS = [
  "*.md",
  "LICENSE",
  ".github/workflows/pages.yml",
  ".github/workflows/check-updates.yml",
  ".github/workflows/release.yml",
  ".github/dependabot.yml",
  ".config/**",
  ".gitignore",
  ".gitattributes",
  ".zed/**",
];

// Pinned cross-rs/cross commit for aarch64-linux cross-compilation (not published to crates.io)
const CROSS_REV = "f86fd03bb70b4c6802847c18087e21391498b0b4";

type Runner = "macos-latest" | "ubuntu-latest" | "windows-latest";

/** A build target platform with its CI configuration. */
interface Target {
  /** GitHub Actions runner OS. */
  runner: Runner;
  /** Rust target triple (e.g. `x86_64-unknown-linux-gnu`). */
  target: string;
  /** Whether to run `cargo test` for this target. */
  runTests?: boolean;
  /** Whether this target requires cross-compilation via `cross`. */
  cross?: boolean;
  /** Whether to include this target in the reduced PR matrix. */
  runOnPr?: boolean;
}

const targets: Target[] = [
  { runner: "macos-latest", target: "x86_64-apple-darwin", runTests: true },
  { runner: "macos-latest", target: "aarch64-apple-darwin", runTests: true, runOnPr: true },
  { runner: "windows-latest", target: "x86_64-pc-windows-msvc", runTests: true },
  { runner: "ubuntu-latest", target: "x86_64-unknown-linux-gnu", runTests: true, runOnPr: true },
  { runner: "ubuntu-latest", target: "aarch64-unknown-linux-gnu", cross: true },
];
const SITE_VERIFY_TARGET = "x86_64-unknown-linux-gnu";

// --- Derived values ---

function zipFileName(t: Target) {
  return `${REPO_NAME}-${t.target}.zip`;
}

function stepId(t: Target) {
  return `pre_release_${t.target.replaceAll("-", "_")}`;
}

// --- Step builders ---
// Each function returns a GitHub Actions step (or array of steps) as a plain
// object that gets serialized to YAML by the `stringify` call at the bottom.

// deno-lint-ignore no-explicit-any
type Step = Record<string, any>;

function checkout(): Step {
  return {
    uses: "actions/checkout@v7",
    with: { submodules: "recursive" },
  };
}

function rustToolchain(): Step {
  return { uses: "dsherret/rust-toolchain-file@v1" };
}

function cargoCache(): Step {
  return {
    name: "Cache cargo",
    uses: "Swatinem/rust-cache@v2",
    with: {
      "prefix-key": "v4-${{matrix.config.target}}",
      "save-if": `\${{ ${BRANCHES.map((b) => `github.ref == 'refs/heads/${b}'`).join(" || ")} }}`,
    },
  };
}

function setupDeno(): Step {
  return { uses: "denoland/setup-deno@v2" };
}

function setupBun(): Step {
  return {
    uses: "oven-sh/setup-bun@v2",
    if: `matrix.config.target == '${SITE_VERIFY_TARGET}'`,
  };
}

function setupJust(): Step {
  return { uses: "extractions/setup-just@v4" };
}

function justCommand(...args: string[]) {
  return ["just", ...args].join(" ");
}

function denoBuildJs(): Step {
  return {
    name: "Build JS",
    run: justCommand("build"),
  };
}

function clearV8Cache(): Step {
  return {
    name: "Clear stale v8 build cache",
    shell: "bash",
    run: "rm -rf target/*/build/v8-*",
  };
}

/** Shared setup sequence used by both check and build jobs. */
function setupSteps(): Step[] {
  return [
    checkout(),
    rustToolchain(),
    cargoCache(),
    clearV8Cache(),
    setupDeno(),
    setupJust(),
    denoBuildJs(),
  ];
}

function setupRustTarget(): Step {
  const appleTargets = targets
    .filter((t) => t.target.includes("apple"))
    .map((t) => `matrix.config.target == '${t.target}'`);
  return {
    name: "Setup Rust target",
    if: appleTargets.join(" || "),
    run: `rustup target add "\${{matrix.config.target}}"`,
  };
}

/** Pre-build JS bundle and install `cross` for cross-compilation targets. */
function setupCross(): Step[] {
  return [
    {
      name: "Install cross",
      if: "matrix.config.cross == 'true'",
      run:
        `cargo install cross --locked --git https://github.com/cross-rs/cross --rev ${CROSS_REV}`,
    },
  ];
}

/** Generate a cargo/cross build step with appropriate conditionals for mode and cross-compilation. */
function cargoBuild(mode: "debug" | "release", cross: boolean): Step {
  const isRelease = mode === "release";
  const crossCond = cross ? "matrix.config.cross == 'true'" : "matrix.config.cross != 'true'";
  const tagCond = isRelease
    ? "startsWith(github.ref, 'refs/tags/')"
    : "!startsWith(github.ref, 'refs/tags/')";
  const recipe = cross
    ? isRelease ? "ci-cross-build-release" : "ci-cross-build-debug"
    : isRelease
    ? "ci-build-release"
    : "ci-build-debug";
  return {
    name: `Build ${cross ? "cross " : ""}(${isRelease ? "Release" : "Debug"})`,
    if: `${crossCond} && ${tagCond}`,
    run: justCommand(recipe, "${{matrix.config.target}}"),
  };
}

function lint(): Step {
  return {
    name: "Lint",
    if:
      "!startsWith(github.ref, 'refs/tags/') && matrix.config.target == 'x86_64-unknown-linux-gnu'",
    run: justCommand("ci-lint"),
  };
}

function test(mode: "debug" | "release"): Step {
  const isRelease = mode === "release";
  const tagCond = isRelease
    ? "startsWith(github.ref, 'refs/tags/')"
    : "!startsWith(github.ref, 'refs/tags/')";
  return {
    name: `Test (${isRelease ? "Release" : "Debug"})`,
    if: `matrix.config.run_tests == 'true' && ${tagCond}`,
    run: justCommand(isRelease ? "ci-test-release" : "ci-test-debug"),
  };
}

/** Zip the release binary and compute its SHA-256 checksum. Uses PowerShell on Windows, bash elsewhere. */
function preRelease(t: Target): Step {
  const isWindows = t.runner === "windows-latest";
  const zip = zipFileName(t);
  const releaseDir = `target/${t.target}/release`;
  const lines = isWindows
    ? [
      `Compress-Archive -CompressionLevel Optimal -Force -Path ${releaseDir}/${REPO_NAME}.exe -DestinationPath ${releaseDir}/${zip}`,
      `$hash = (Get-FileHash -Algorithm SHA256 ${releaseDir}/${zip}).Hash.ToLower()`,
      `"ZIP_CHECKSUM=$hash" >> $env:GITHUB_OUTPUT`,
    ]
    : [
      `zip -r ${zip} ${REPO_NAME}`,
      `checksum="$(shasum -a 256 ${zip} | awk '{print $1}')"`,
      `echo "ZIP_CHECKSUM=\${checksum}" >> "\${GITHUB_OUTPUT}"`,
    ];
  const step: Step = {
    name: `Pre-release (${t.target})`,
    id: stepId(t),
    if: `matrix.config.target == '${t.target}' && startsWith(github.ref, 'refs/tags/')`,
    run: lines.join("\n"),
  };
  if (isWindows) {
    step.shell = "pwsh";
  } else {
    step["working-directory"] = releaseDir;
  }
  return step;
}

function uploadReleaseAsset(t: Target): Step {
  return {
    name: `Upload release asset (${t.target})`,
    if: `matrix.config.target == '${t.target}' && startsWith(github.ref, 'refs/tags/')`,
    shell: "bash",
    env: { GH_TOKEN: "${{ github.token }}" },
    run: `gh release upload "\${GITHUB_REF#refs/tags/}" target/${t.target}/release/${
      zipFileName(t)
    } --clobber --repo "\${GITHUB_REPOSITORY}"`,
  };
}

function verifySchemaAndSite(): Step {
  return {
    name: "Verify schema and site",
    if: `matrix.config.target == '${SITE_VERIFY_TARGET}'`,
    run: justCommand("ci-verify-schema-site"),
  };
}

// --- Job builders ---

/** Convert target definitions into a GitHub Actions matrix configuration. */
function matrixConfig(items: Target[]) {
  return {
    config: items.map((t) => ({
      os: t.runner,
      run_tests: (t.runTests ?? false).toString(),
      cross: (t.cross ?? false).toString(),
      target: t.target,
    })),
  };
}

/**
 * Create a CI build job with the given targets and event condition.
 * Used for both the PR `check` job (reduced matrix) and the push `build` job (full matrix).
 */
function buildJob(
  items: Target[],
  condition: string,
  opts?: { includeRelease?: boolean },
) {
  const includeRelease = opts?.includeRelease ?? true;
  return {
    name: "${{ matrix.config.target }}",
    if: condition,
    permissions: { contents: includeRelease ? "write" : "read" },
    "runs-on": "${{ matrix.config.os }}",
    strategy: { matrix: matrixConfig(items) },
    env: { CARGO_INCREMENTAL: 0, RUST_BACKTRACE: "full" },
    steps: [
      ...setupSteps(),
      setupBun(),
      setupRustTarget(),
      ...setupCross(),
      cargoBuild("debug", false),
      cargoBuild("release", false),
      cargoBuild("debug", true),
      cargoBuild("release", true),
      lint(),
      verifySchemaAndSite(),
      test("debug"),
      test("release"),
      ...(includeRelease ? items.map(preRelease) : []),
      ...(includeRelease ? items.map(uploadReleaseAsset) : []),
    ],
  };
}

/** Generate the GitHub Release body with install instructions. */
function releaseBody(): string {
  const tag = "${{ steps.get_tag_version.outputs.TAG_VERSION }}";
  const checksum = "${{ steps.get_plugin_file_checksum.outputs.CHECKSUM }}";
  const version = "${{ steps.get_svgo_version.outputs.SVGO_VERSION }}";
  const pluginUrl =
    `https://github.com/${REPO_OWNER}/${REPO_NAME}/releases/download/${tag}/plugin.json@${checksum}`;

  return `\
# SVGO ${version}

## Install

Dependencies:

- Install dprint's CLI >= 0.40.0

In a dprint configuration file:

1. Specify the plugin url and checksum in the \`"plugins"\` array or run \`dprint add ${REPO_OWNER}/${
    REPO_NAME.replace("dprint-plugin-", "")
  }\`:

   \`\`\`jsonc
   {
     // etc...
     "plugins": [
       // ...add other dprint plugins here...
       "${pluginUrl}"
     ]
   }
   \`\`\`

2. Add a \`"svgo"\` configuration property if desired.

   \`\`\`jsonc
   {
     // ...etc...
     "svgo": {
        "pretty": true,
        "indent": 2
      }
   }
   \`\`\`
`;
}

/** Create the empty draft release that build jobs stream their assets into. */
function createReleaseJob() {
  return {
    name: "create_release",
    if: "startsWith(github.ref, 'refs/tags/')",
    "runs-on": "ubuntu-latest",
    permissions: { contents: "write" },
    steps: [
      {
        name: "Create draft release",
        env: { GH_TOKEN: "${{ github.token }}" },
        run: [
          'TAG="${GITHUB_REF#refs/tags/}"',
          'gh release view "${TAG}" --repo "${GITHUB_REPOSITORY}" ||',
          '  gh release create "${TAG}" --repo "${GITHUB_REPOSITORY}" --draft --title "${TAG}" --notes "Assets are being uploaded by CI."',
        ].join("\n"),
      },
    ],
  };
}

/** Finish the draft release: add plugin.json and schema.json, write the body, publish. */
function publishReleaseJob() {
  const ghToken = () => ({ GH_TOKEN: "${{ github.token }}" });
  return {
    name: "publish_release",
    if: "startsWith(github.ref, 'refs/tags/')",
    needs: "build",
    "runs-on": "ubuntu-latest",
    permissions: { contents: "write" },
    steps: [
      {
        name: "Checkout",
        uses: "actions/checkout@v7",
        with: { submodules: "recursive" },
      },
      setupDeno(),
      setupJust(),
      {
        name: "Generate schema",
        run: "deno run --frozen -A scripts/generate_schema.ts schema.json",
      },
      {
        name: "Download release assets",
        env: ghToken(),
        run:
          'gh release download "${GITHUB_REF#refs/tags/}" --repo "${GITHUB_REPOSITORY}" --pattern "*.zip"',
      },
      {
        name: "Output checksums",
        run: targets
          .flatMap((t) => [
            `checksum="$(shasum -a 256 ${zipFileName(t)} | awk '{print $1}')"`,
            `echo "${zipFileName(t)}: \${checksum}"`,
          ])
          .join("\n"),
      },
      {
        name: "Create plugin file",
        run: justCommand("ci-create-plugin-file"),
      },
      {
        name: "Get svgo version",
        id: "get_svgo_version",
        run: [
          'svgo_version="$(just ci-output-svgo-version)"',
          'echo "SVGO_VERSION=${svgo_version}" >> "${GITHUB_OUTPUT}"',
        ].join("\n"),
      },
      {
        name: "Get tag version",
        id: "get_tag_version",
        run: 'echo "TAG_VERSION=${GITHUB_REF/refs\\/tags\\//}" >> "${GITHUB_OUTPUT}"',
      },
      {
        name: "Get plugin file checksum",
        id: "get_plugin_file_checksum",
        run: [
          `checksum="$(shasum -a 256 plugin.json | awk '{print $1}')"`,
          'echo "CHECKSUM=${checksum}" >> "${GITHUB_OUTPUT}"',
        ].join("\n"),
      },
      {
        name: "Upload plugin file and schema",
        env: ghToken(),
        run:
          'gh release upload "${{ steps.get_tag_version.outputs.TAG_VERSION }}" plugin.json schema.json --clobber --repo "${GITHUB_REPOSITORY}"',
      },
      {
        name: "Publish release",
        env: ghToken(),
        run: [
          "cat > release_body.md <<'RELEASE_BODY'",
          releaseBody(),
          "RELEASE_BODY",
          'gh release edit "${{ steps.get_tag_version.outputs.TAG_VERSION }}" --repo "${GITHUB_REPOSITORY}" --title "${{ steps.get_tag_version.outputs.TAG_VERSION }} - SVGO ${{ steps.get_svgo_version.outputs.SVGO_VERSION }}" --notes-file release_body.md --draft=false',
        ].join("\n"),
      },
    ],
  };
}

// --- Assemble and write ---

const prTargets = targets.filter((t) => t.runOnPr);

const ci = {
  name: "CI",
  on: {
    pull_request: { branches: [...BRANCHES], "paths-ignore": [...IGNORED_PATHS] },
    push: { branches: [...BRANCHES], tags: ["*"], "paths-ignore": [...IGNORED_PATHS] },
  },
  permissions: { contents: "read" },
  concurrency: {
    group: "${{ github.workflow }}-${{ github.event.pull_request.number || github.sha }}",
    "cancel-in-progress": true,
  },
  jobs: {
    check: buildJob(prTargets, "github.event_name == 'pull_request'", {
      includeRelease: false,
    }),
    create_release: createReleaseJob(),
    build: {
      ...buildJob(
        targets,
        "!cancelled() && github.event_name == 'push' && (needs.create_release.result == 'success' || needs.create_release.result == 'skipped')",
      ),
      needs: "create_release",
    },
    publish_release: publishReleaseJob(),
  },
};

let output = "# GENERATED BY ./ci.generate.ts -- DO NOT DIRECTLY EDIT\n\n";
output += stringify(ci, {
  lineWidth: 10_000,
  defaultStringType: "QUOTE_DOUBLE",
  defaultKeyType: "PLAIN",
});

Deno.writeTextFileSync(new URL("./ci.yml", import.meta.url), output);
try {
  await $`dprint fmt`;
} catch {
  // dprint may not be installed; formatting is optional
}

