async function writeLocalTestConfig(workspaceDirPath: string, pluginChecksum: string) {
  const config = {
    $schema: "https://dprint.dev/schemas/v0.json",
    includes: ["**/*.svg"],
    plugins: [`./plugin.json@${pluginChecksum}`],
